    (" 2 H ", 7200), ("3MiN", 180), ("\t4 seconds\n", 4),
    ("1 h\t5 M", 3900), ("01s", 1),
    ("0s", 0), ("0 minutes", 0), ("0h0m0s", 0),
    ("", None), ("   ", None), ("1.5h", None),
    ("-1m", None), ("+2s", None), ("1:30", None),
